### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

// 返回所选砝码的升序重量；无解返回空向量
vector<int> choose_weights(int n, long long k) {
    long long S = 1LL * n * (n + 1) / 2;
    if (k > S) return {};
    vector<int> ans;
    for (int w = n; w >= 1; --w) {
        if (k >= w) {
            ans.push_back(w);
            k -= w;
            if (k == 0) break;
        }
    }
    if (k != 0) return {}; // 理论上不会发生
    reverse(ans.begin(), ans.end()); // 转为升序
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    vector<string> out;
    while (T--) {
        int n, m;
        cin >> n >> m;
        for (int i = 0; i < m; ++i) {
            long long k;
            cin >> k;
            vector<int> res = choose_weights(n, k);
            if (res.empty()) {
                out.emplace_back("-1");
            } else {
                out.emplace_back(to_string(res.size()));
                string line;
                for (size_t j = 0; j < res.size(); ++j) {
                    if (j) line.push_back(' ');
                    line += to_string(res[j]);
                }
                out.emplace_back(line);
            }
        }
    }
    for (auto &s : out) cout << s << "\n";
    return 0;
}
